'use strict';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),D=window.GAECHEON_DATA;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={grade:'3-4',index:0,beat:0,selected:null,view:'home',answers:{},activity:{order:[],classes:{},choice:null,reflection:''}};
const labels={story:'전해지는 이야기',history:'전승과 역사',evidence:'자료의 단서',quiz:'골든벨',fact:'알아보기',value:'오늘의 실천',activity:'학생 참여',source:'문헌 탐구',inquiry:'주장과 근거',cover:'시작하기',exit:'배움 정리',observe:'이미지 관찰'};
function route(){if(modal.open)modal.close();const m=location.hash.match(/^#(lesson|student)\/(1-2|3-4|5-6)(?:\/(\d+))?/);if(m){state.view=m[1];state.grade=m[2];state.index=Math.min(Math.max(0,Number(m[3]||0)),D.grades[state.grade].slides.length-1);state.beat=0;state.selected=null;render()}else{state.view='home';render()}}
function home(){document.body.className='home-mode';app.innerHTML=`<header class="g-head"><a href="index.html" class="g-brand"><b>ㄱ</b><span>오늘의 국경일<small>개천절 교육자료</small></span></a><a href="index.html" class="head-link">← 다섯 국경일</a></header><main id="main" class="g-home"><section class="g-hero"><img src="assets/gaecheon-dawn.png" alt="한국의 산과 소나무 사이로 해가 떠오르는 생성 삽화"><div class="g-hero-wash"></div><div class="g-hero-copy"><span class="overline">OCTOBER 03 · NATIONAL FOUNDATION DAY</span><h1>하늘이 열린 이야기,<br><em>사람을 이롭게 하는 마음.</em></h1><p>개천절의 전승과 고조선의 역사를 구분하며<br>우리 교실에서 홍익인간의 뜻을 찾아봅니다.</p><span class="hero-note">한국의 산을 상징적으로 그린 교육용 생성 삽화</span></div></section><section class="grade-chooser"><div class="chooser-heading"><span class="overline dark">CHOOSE YOUR CLASS</span><h2>우리 반의 배움 길을 골라 주세요</h2><p>전자칠판에서 ‘다음’만 눌러 질문과 설명을 차례대로 펼칩니다.</p></div><div class="grade-cards">${Object.entries(D.grades).map(([id,g],i)=>`<a class="grade-card" href="#lesson/${id}/0"><div class="grade-art"><img src="assets/${['gaecheon-bear-tiger','gaecheon-tree','gaecheon-community'][i]}.png" alt="${['곰과 범의 상상 삽화','산의 나무를 표현한 삽화','청동기 마을의 교육용 재구성'][i]}"></div><div class="grade-meta"><span>${g.label}</span><strong>0${i+1}</strong></div><h3>${esc(g.subtitle)}</h3><p>${esc(g.focus)}</p><div class="grade-foot"><span>${g.slides.length}장면 · 약 40분</span><b>수업 열기 ↗</b></div></a>`).join('')}</div><aside class="fact-strip"><b>교사를 위한 역사 표현 기준</b><p>개천절은 10월 3일. 하늘이 열렸다는 이야기와 고조선의 시작을 기립니다. 이야기의 날짜와 장면을 고대의 확정된 사실처럼 설명하지 않습니다.</p><button data-action="sources">근거 자료 보기 ↗</button></aside></section><footer class="g-footer"><span>그림은 교육용 상상 삽화 · 학생 활동은 기기에만 저장</span><a href="index.html">국경일 모아 보기 ↗</a></footer></main>`}
function picture(s){return `<img class="slide-photo" src="assets/${esc(s.image)}.png" alt="${esc(s.kind==='story'?'전승을 상상하여 표현한 삽화':s.kind==='history'||s.kind==='evidence'?'자료를 참고한 교육용 재구성':'개천절 교육용 생성 삽화')}">${s.kind==='inquiry'?'<img class="skia-card" src="assets/gaecheon-fact-skia.png" alt="10월 3일은 기념하는 날이며 정확한 고대 사건 날짜로 확정되지 않았음을 알리는 타이포그래픽">':''}`}
function choices(s){if(!s.choices)return'';return `<div class="quiz-choices ${typeof s.choices[0]==='object'?'picture-options':''}">${s.choices.map((x,i)=>{const obj=typeof x==='object'?x:{text:x};return `<button class="quiz-choice ${state.selected===i?'picked':''} ${state.beat&&i===s.correct?'correct':''} ${state.beat&&state.selected===i&&i!==s.correct?'wrong':''}" data-choice="${i}" ${state.beat?'disabled':''}><span class="choice-index">${i+1}</span>${obj.image?`<img src="assets/${esc(obj.image)}.png" alt="">`:''}<span>${esc(obj.text)}</span></button>`}).join('')}</div>`}
function slide(){const g=D.grades[state.grade],s=g.slides[state.index],count=g.slides.length,step=state.index+1;document.body.className='presenter-mode';app.innerHTML=`<div class="presenter-shell" id="main"><header class="presenter-head"><a href="index.html" class="mini-brand">ㄱ <span>국경일 모아 보기</span></a><div class="presenter-context"><b>개천절</b><span>${g.label} · ${esc(g.subtitle)}</span></div><div class="presenter-tools"><button data-action="replay" title="현재 장면의 글자 모션 다시 보기">↺ 다시 보기</button><button data-action="notes" title="교사용 발문과 정확한 표현">교사 노트</button><button data-action="sources" title="공식 근거 자료">자료 출처</button><button data-action="full" title="전자칠판 전체 화면">⛶ 전체 화면</button></div></header><section class="slide-canvas" aria-label="${esc(s.title)}"><div class="slide-image">${picture(s)}<div class="image-credit">${s.kind==='history'||s.kind==='evidence'?'고고학 자료를 참고한 교육용 상상 재구성':s.kind==='story'?'『삼국유사』 전승을 상상한 교육용 삽화':'교육용 생성 삽화 · 실제 역사 사진 아님'}</div></div><div class="slide-content" id="motion-content"><span class="slide-kicker"><i></i>${esc(s.tag||labels[s.kind])}</span><div class="slide-main"><span class="slide-number">${String(step).padStart(2,'0')} / ${String(count).padStart(2,'0')}</span><h1>${esc(s.title)}</h1><p class="slide-question">${esc(s.question)}</p>${choices(s)}${s.kind==='activity'?`<button class="qr-inline" data-action="qr">학생 태블릿 QR 열기 ↗</button>`:''}<div class="answer ${state.beat?'visible':''}" aria-live="polite"><b>${s.kind==='quiz'?'정답과 이유':'함께 정리'}</b><p>${esc(s.answer)}</p></div></div><div class="slide-bottom"><span class="step-guide">${state.beat?'설명과 이유를 나누어 주세요':'먼저 학생의 생각을 들어 주세요'}</span><span>${s.minutes}분 권장</span></div></div></section><footer class="presenter-foot"><div class="foot-left"><span class="progress-label">수업 진행</span><div class="progress"><span style="width:${((state.index+state.beat/2+1)/count)*100}%"></span></div><b>${step} / ${count}</b></div><div class="foot-controls"><button data-action="prev" ${step===1&&!state.beat?'disabled':''}>← 이전</button><button class="next" data-action="next">${state.beat?(step===count?'수업 마치기':'다음 장면 →'):'설명 보기 →'}</button></div></footer></div>`;if(state.beat)document.querySelector('.answer')?.classList.add('visible')}
function student(){const g=D.grades[state.grade];document.body.className='student-mode';app.innerHTML=`<header class="student-head"><a href="index.html">ㄱ 오늘의 국경일</a><span>개천절 · ${g.label}</span></header><main id="main" class="student-main"><div class="student-title"><span class="overline dark">TABLET ACTIVITY</span><h1>나의 개천절 탐험</h1><p>그림을 보고 먼저 혼자 생각한 뒤, 짝에게 이유를 말해 주세요.</p></div><nav class="activity-tabs"><button data-tab="story" class="${state.activity.tab!=='class'&&state.activity.tab!=='act'?'on':''}">① 이야기</button><button data-tab="class" class="${state.activity.tab==='class'?'on':''}">② 자료 구분</button><button data-tab="act" class="${state.activity.tab==='act'?'on':''}">③ 우리 반 실천</button></nav><div class="activity-panel">${activityBody()}</div><p class="privacy">이 활동은 학생 이름이나 응답을 서버로 보내지 않습니다. 교사에게 말이나 학습지로 공유해 주세요.</p></main>`}
function activityBody(){const a=state.activity,g=state.grade,tab=a.tab||'story';if(tab==='story'){const order=[2,0,3,1],items=[['하늘이 열린 전승','gaecheon-dawn'],['신단수 아래 이야기','gaecheon-tree'],['곰과 범의 이야기','gaecheon-bear-tiger'],['단군왕검과 고조선','gaecheon-community']];return `<h2>이야기를 순서대로 놓아 볼까요?</h2><p>그림을 눌러 차례대로 고르세요. 모든 장면은 <b>전해지는 이야기나 교육용 상상 그림</b>입니다.</p><div class="student-grid">${order.map(i=>`<button class="story-option ${a.order.includes(i)?'chosen':''}" data-story="${i}" ${a.order.includes(i)?'disabled':''}><img src="assets/${items[i][1]}.png" alt=""><span>${items[i][0]}</span></button>`).join('')}</div><div class="selected-sequence">내가 고른 순서: ${a.order.map(i=>items[i][0]).join(' → ')||'아직 없음'}</div><div class="activity-actions"><button data-action="story-reset">다시 고르기</button>${a.order.length===4?`<span class="feedback ${a.order.join(',')==='0,1,2,3'?'good':'again'}">${a.order.join(',')==='0,1,2,3'?'잘했어요! 이야기의 흐름을 짝에게 설명해 보세요.':'순서를 다시 생각해 보세요. 하늘 이야기부터 시작해요.'}</span>`:''}</div>`}
if(tab==='class'){const questions=g==='1-2'?[['곰이 사람이 되었다는 장면','전승'],['개천절은 10월 3일','사실']]:g==='3-4'?[['『삼국유사』에 단군 이야기가 적혀 있다','사실'],['곰이 사람으로 변했다는 이야기','전승'],['화면 속 마을 그림','상상']]:[['『삼국유사』는 단군 이야기를 전한다','사실'],['단군이 10월 3일 나라를 세웠다는 이야기','전승'],['이 화면의 마을 그림','상상'],['비파형 동검은 출토된 유물이다','사실']];return `<h2>사실, 전승, 상상 그림</h2><p>각 문장을 살펴보고 알맞은 종류를 골라 보세요. ‘전승’은 옛이야기로 전해지는 내용이에요.</p><div class="class-list">${questions.map(([q,correct],i)=>`<div class="class-row"><b>${esc(q)}</b><div>${['사실','전승','상상'].map(v=>`<button data-class="${i}" data-value="${v}" class="${a.classes[i]===v?'on':''}">${v}</button>`).join('')}</div>${a.classes[i]?`<small class="${a.classes[i]===correct?'good':'again'}">${a.classes[i]===correct?'좋아요. 까닭을 설명해 보세요.':'다시 살펴보세요. 기록·실제 유물·상상 삽화를 구분해요.'}</small>`:''}</div>`).join('')}</div>`}
const options=g==='1-2'?['친구와 함께 교실을 정리해요','어려운 친구를 모른 척해요','내 것만 챙겨요']:['도움이 필요한 사람의 의견을 듣고 함께 방법을 정해요','친구의 생각을 묻지 않고 대신 결정해요','좋아 보이게 사진만 찍어요'];return `<h2>우리 반에서 홍익인간</h2><p>사람을 널리 이롭게 한다는 뜻을 오늘의 행동으로 바꿔 봅시다.</p><div class="action-choices">${options.map((o,i)=>`<button data-act="${i}" class="${a.choice===i?'on':''}">${esc(o)}</button>`).join('')}</div>${a.choice!==null?`<div class="feedback ${a.choice===0?'good':'again'}">${a.choice===0?'상대의 생각을 존중하며 돕는 행동이에요.':'그 행동이 모두에게 이로울지 다시 생각해 보세요.'}</div>`:''}<label class="reflection">내가 해 볼 한 가지 행동<textarea data-reflection placeholder="예: 친구의 의견을 듣고 함께 정리하기">${esc(a.reflection)}</textarea></label><p class="save-note">적은 내용은 이 화면에만 남아요. 친구나 선생님에게 직접 말해 주세요.</p>`}
function openModal(body){modal.innerHTML=`<button class="close-modal" data-action="close" aria-label="닫기">×</button>${body}`;modal.showModal()}
function sourceList(){openModal(`<span class="overline dark">HISTORICAL SOURCES</span><h2>사실과 전승의 근거</h2><p>개천절의 법적 의미, 단군 이야기의 출처, 청동기 유물의 범위를 구분했습니다.</p><ul class="source-list">${D.sources.map(x=>`<li><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a></li>`).join('')}</ul><p class="source-caveat">모든 삽화는 생성한 교육용 상상 그림입니다. 정확한 고대 복식이나 건물, 사건 날짜의 증거로 쓰지 않습니다.</p>`)}
function qr(){const url=new URL(location.href);url.hash=`student/${state.grade}`;const href=url.href;let svg='';try{const q=window.qrcode(0,'M');q.addData(href);q.make();svg=q.createSvgTag({cellSize:5,margin:4,scalable:true})}catch{svg='<p>QR을 불러오지 못했습니다. 아래 주소를 직접 열어 주세요.</p>'}openModal(`<span class="overline dark">STUDENT TABLET</span><h2>${D.grades[state.grade].label} 학생 활동</h2><p>태블릿 카메라로 스캔하면 개인 활동 화면이 열립니다.</p><div class="qr-art">${svg}</div><a class="share-url" href="${esc(href)}" target="_blank" rel="noopener">학생 화면 직접 열기 ↗</a><p class="qr-url">${esc(href)}</p><p class="source-caveat">교실에서 인터넷 접속이 가능한 배포 주소를 사용하세요. localhost 주소는 교사 컴퓨터에서만 열립니다.</p>`)}
function render(){if(state.view==='lesson')slide();else if(state.view==='student')student();else{home();const grid=document.querySelector('.grade-cards');grid?.insertAdjacentHTML('afterend',`<div class="worksheet-links"><div><strong>인쇄 학습지</strong><span>학생용과 교사용 해설 · 각 2쪽</span></div>${Object.keys(D.grades).map(id=>`<div class="worksheet-grade"><b>${D.grades[id].label}</b><a href="worksheets/gaecheon-${id}-student.pdf" target="_blank" rel="noopener">학생용 ↗</a><a href="worksheets/gaecheon-${id}-teacher.pdf" target="_blank" rel="noopener">교사용 ↗</a></div>`).join('')}</div>`)}}
function next(){const slides=D.grades[state.grade].slides;if(!state.beat){state.beat=1;render();return}if(state.index<slides.length-1){state.index++;state.beat=0;state.selected=null;history.replaceState(null,'',`#lesson/${state.grade}/${state.index}`);render()}else location.hash=''}
function prev(){if(state.beat){state.beat=0;render();return}if(state.index>0){state.index--;state.beat=0;state.selected=null;history.replaceState(null,'',`#lesson/${state.grade}/${state.index}`);render()}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.choice!==undefined){state.selected=Number(b.dataset.choice);render();return}if(b.dataset.tab){state.activity.tab=b.dataset.tab;render();return}if(b.dataset.story!==undefined){state.activity.order.push(Number(b.dataset.story));render();return}if(b.dataset.class!==undefined){state.activity.classes[b.dataset.class]=b.dataset.value;render();return}if(b.dataset.act!==undefined){state.activity.choice=Number(b.dataset.act);render();return}switch(b.dataset.action){case'next':next();break;case'prev':prev();break;case'story-reset':state.activity.order=[];render();break;case'qr':qr();break;case'notes':{const s=D.grades[state.grade].slides[state.index];openModal(`<span class="overline dark">TEACHER'S NOTE</span><h2>${esc(s.title)}</h2><p class="note-lead">${esc(s.note)}</p><p><b>학생에게 건넬 질문</b><br>${esc(s.question)}</p><p><b>정리할 말</b><br>${esc(s.answer)}</p><p class="source-caveat">권장 시간 ${s.minutes}분 · 영상 없이 그림과 말만으로 진행 가능</p>`);break}case'sources':sourceList();break;case'close':modal.close();break;case'full':try{document.fullscreenElement?await document.exitFullscreen():await document.documentElement.requestFullscreen()}catch{}break;case'replay':{const el=document.querySelector('#motion-content');if(el){el.classList.remove('animate');void el.offsetWidth;el.classList.add('animate')}break}}});
document.addEventListener('input',e=>{if(e.target.matches('[data-reflection]'))state.activity.reflection=e.target.value});
document.addEventListener('keydown',e=>{if(state.view!=='lesson'||modal.open||/^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)||e.target.isContentEditable)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();next()}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();prev()}});
window.addEventListener('hashchange',route);route();
